/**
 * Server-rendered public project pages.
 *
 * `GET /projects` is delegated to the static export (the showcase index).
 * `GET /projects/<slug>` prefers a pre-rendered static page if one exists;
 * otherwise it looks the approved project up in D1 and renders a complete,
 * self-contained HTML document.
 *
 * IMPORTANT: this markup is generated by the Worker, so it cannot rely on the
 * static export's compiled Tailwind CSS. All styling lives in the inline
 * `<style>` block below, mirroring the site's dark aesthetic.
 */

import { htmlResponse, escapeHtml, jsonScript, paragraphs } from "../lib/html.js";
import { safeHttpUrl, splitList, truncate } from "../lib/format.js";
import { methodNotAllowed } from "../lib/json.js";
import { notFoundPage } from "../lib/assets.js";

const SITE_URL = "https://buildforgood.nikhilnagpure203.workers.dev";
const SITE_NAME = "Build For Good";
const DEFAULT_OG_IMAGE = `${SITE_URL}/og.png`;

/** Columns needed to render a project page. */
const SSR_FIELDS = [
  "id",
  "slug",
  "title",
  "one_liner",
  "description",
  "disciplines",
  "stage",
  "url",
  "repo",
  "demo",
  "cover_image",
  "lead_name",
  "location",
  "team",
  "tags",
  "featured",
  "created_at",
].join(", ");

/**
 * Handle `/projects` and `/projects/*`.
 *
 * @param {Request} request
 * @param {{DB: D1Database, ASSETS: Fetcher}} env
 * @param {ExecutionContext} ctx
 * @param {URL} url
 * @returns {Promise<Response>}
 */
export async function handleProjects(request, env, ctx, url) {
  const method = request.method;
  if (method !== "GET" && method !== "HEAD") {
    return methodNotAllowed("GET, HEAD, OPTIONS");
  }

  // Normalise a trailing slash so `/projects/` behaves like `/projects`.
  const pathname = url.pathname.replace(/\/+$/, "") || "/";

  // The showcase index is a static page.
  if (pathname === "/projects") {
    // Static export generates `projects.html` not `projects/index.html`.
    // Rewrite the request path so Assets binding finds the correct file.
    const assetUrl = new URL(request.url);
    assetUrl.pathname = "/projects.html";
    return env.ASSETS.fetch(new Request(assetUrl, request));
  }

  const prefix = "/projects/";
  if (!pathname.startsWith(prefix)) {
    return env.ASSETS.fetch(request);
  }

  const slug = decodeURIComponent(pathname.slice(prefix.length));
  if (!slug || slug.includes("/")) {
    return notFoundPage(env, url);
  }

  // 1. Prefer a static page shipped with the export, if one exists for this
  //    slug. A missing path yields the export's 404 page (status 404).
  const asset = await env.ASSETS.fetch(request);
  if (asset.status !== 404) return asset;

  // 2. Fall back to D1, approved projects only, and server-render the page.
  let project = null;
  try {
    project = await env.DB.prepare(
      `SELECT ${SSR_FIELDS} FROM projects WHERE slug = ? AND status = 'approved' LIMIT 1`,
    )
      .bind(slug)
      .first();
  } catch (err) {
    console.error("projects-ssr: D1 query failed", err);
  }

  // 3. Not found (or D1 failed): return the export's 404 document.
  if (!project) return asset;

  return htmlResponse(renderProject(project), 200, {
    "cache-control": "public, max-age=300",
    "x-robots-tag": "all",
  });
}

/* ------------------------------------------------------------------ */
/* Rendering                                                           */
/* ------------------------------------------------------------------ */

/**
 * Build the complete HTML document for one project.
 * Every DB value is escaped before it reaches the markup.
 *
 * @param {Record<string, unknown>} project
 * @returns {string}
 */
export function renderProject(project) {
  const slug = String(project.slug ?? "");
  const title = String(project.title ?? "Project");
  const oneLiner = String(project.one_liner ?? "");
  const description = String(project.description ?? "");

  const canonical = `${SITE_URL}/projects/${encodeURIComponent(slug)}`;
  const metaDescription = truncate(oneLiner || description, 155);

  const coverImage = safeHttpUrl(project.cover_image) || DEFAULT_OG_IMAGE;

  const disciplines = splitList(project.disciplines);
  const tags = splitList(project.tags);

  // --- Meta row (only show values that exist) --------------------------
  const metaItems = [];
  if (project.lead_name) metaItems.push(["Lead", String(project.lead_name)]);
  if (project.location) metaItems.push(["Location", String(project.location)]);
  if (project.stage) metaItems.push(["Stage", String(project.stage)]);
  if (disciplines.length) metaItems.push(["Disciplines", disciplines.join(" \u00b7 ")]);

  // --- Outbound links --------------------------------------------------
  const links = [];
  if (safeHttpUrl(project.url)) links.push(["Visit", safeHttpUrl(project.url)]);
  if (safeHttpUrl(project.repo)) links.push(["Repository", safeHttpUrl(project.repo)]);
  if (safeHttpUrl(project.demo)) links.push(["Demo", safeHttpUrl(project.demo)]);

  // --- JSON-LD ---------------------------------------------------------
  const ld = {
    "@context": "https://schema.org",
    "@type": "CreativeWork",
    name: title,
    description: metaDescription || oneLiner || undefined,
    url: canonical,
    creator: project.lead_name
      ? { "@type": "Person", name: String(project.lead_name) }
      : undefined,
    dateCreated: project.created_at ? String(project.created_at) : undefined,
    isPartOf: { "@id": `${SITE_URL}/#organization` },
  };
  if (tags.length) ld.keywords = tags.join(", ");
  if (disciplines.length) ld.about = disciplines.join(", ");

  const coverMarkup = safeHttpUrl(project.cover_image)
    ? `<img class="cover" src="${escapeHtml(coverImage)}" alt="${escapeHtml(title)}" loading="lazy" />`
    : "";

  const metaMarkup = metaItems.length
    ? `<ul class="meta">${metaItems
        .map(
          ([label, value]) =>
            `<li><span class="meta-label">${escapeHtml(label)}</span> ${escapeHtml(value)}</li>`,
        )
        .join("")}</ul>`
    : "";

  const tagsMarkup = tags.length
    ? `<ul class="tags">${tags
        .map((tag) => `<li>${escapeHtml(tag)}</li>`)
        .join("")}</ul>`
    : "";

  const linksMarkup = links.length
    ? `<nav class="links" aria-label="Project links">${links
        .map(
          ([label, href]) =>
            `<a href="${escapeHtml(href)}" rel="noopener noreferrer" target="_blank">${escapeHtml(label)} <span aria-hidden="true">\u2197</span></a>`,
        )
        .join("")}</nav>`
    : "";

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${escapeHtml(title)} \u2014 ${SITE_NAME}</title>
<meta name="description" content="${escapeHtml(metaDescription)}" />
<link rel="canonical" href="${escapeHtml(canonical)}" />
<meta name="robots" content="index, follow" />
<meta name="theme-color" content="#07060a" />

<meta property="og:type" content="article" />
<meta property="og:site_name" content="${SITE_NAME}" />
<meta property="og:title" content="${escapeHtml(title)}" />
<meta property="og:description" content="${escapeHtml(metaDescription)}" />
<meta property="og:url" content="${escapeHtml(canonical)}" />
<meta property="og:image" content="${escapeHtml(coverImage)}" />

<meta name="twitter:card" content="summary_large_image" />
<meta name="twitter:title" content="${escapeHtml(title)}" />
<meta name="twitter:description" content="${escapeHtml(metaDescription)}" />
<meta name="twitter:image" content="${escapeHtml(coverImage)}" />

<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link href="https://fonts.googleapis.com/css2?family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet" />

<script type="application/ld+json">${jsonScript(ld)}</script>

<style>
  :root {
    color-scheme: dark;
    --bg: #07060a;
    --fg: #f4f2ee;
    --muted: #9b98a3;
    --accent: #eca8d6;
    --border: rgba(244, 242, 238, 0.12);
    --card: rgba(244, 242, 238, 0.03);
  }
  * { box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    margin: 0;
    background: var(--bg);
    color: var(--fg);
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
      Helvetica, Arial, sans-serif;
    line-height: 1.65;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
  }
  a { color: var(--accent); text-decoration: none; }
  a:hover { text-decoration: underline; }
  .wrap { max-width: 760px; margin: 0 auto; padding: 32px 24px 96px; }

  header.site {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding-bottom: 24px;
    margin-bottom: 48px;
    border-bottom: 1px solid var(--border);
  }
  .brand {
    font-family: "Instrument Serif", Georgia, serif;
    font-size: 1.2rem;
    color: var(--fg);
    letter-spacing: 0.01em;
  }
  .brand:hover { text-decoration: none; color: var(--accent); }
  header.site nav a { font-size: 0.85rem; color: var(--muted); }
  header.site nav a:hover { color: var(--accent); }

  .eyebrow {
    margin: 0;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    font-size: 0.7rem;
    color: var(--accent);
  }
  h1 {
    font-family: "Instrument Serif", Georgia, serif;
    font-weight: 400;
    font-size: clamp(2.4rem, 6vw, 3.6rem);
    line-height: 1.06;
    letter-spacing: -0.01em;
    margin: 10px 0 18px;
  }
  .lede { font-size: 1.18rem; color: #d8d5cf; margin: 0 0 28px; max-width: 62ch; }
  .cover {
    display: block;
    width: 100%;
    border: 1px solid var(--border);
    border-radius: 10px;
    margin: 0 0 36px;
  }
  .meta {
    list-style: none;
    display: flex;
    flex-wrap: wrap;
    gap: 10px 24px;
    margin: 0 0 40px;
    padding: 0;
    font-size: 0.9rem;
    color: var(--muted);
  }
  .meta-label {
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-size: 0.66rem;
    margin-right: 6px;
    color: var(--accent);
  }
  .description { font-size: 1.05rem; color: #e7e4df; }
  .description p { margin: 0 0 1.15em; }
  .tags {
    list-style: none;
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 40px 0 0;
    padding: 0;
  }
  .tags li {
    border: 1px solid var(--border);
    border-radius: 999px;
    padding: 4px 12px;
    font-size: 0.78rem;
    color: var(--muted);
  }
  .links { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 36px; }
  .links a {
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 10px 18px;
    color: var(--fg);
    background: var(--card);
    font-size: 0.92rem;
  }
  .links a:hover { border-color: var(--accent); color: var(--accent); text-decoration: none; }
  footer.site {
    margin-top: 72px;
    padding-top: 24px;
    border-top: 1px solid var(--border);
    display: flex;
    flex-wrap: wrap;
    gap: 18px;
    font-size: 0.85rem;
    color: var(--muted);
  }
</style>
</head>
<body>
<div class="wrap">
  <header class="site">
    <a class="brand" href="/">${SITE_NAME}</a>
    <nav><a href="/projects">All projects</a></nav>
  </header>

  <main>
    <p class="eyebrow">Project</p>
    <h1>${escapeHtml(title)}</h1>
    ${oneLiner ? `<p class="lede">${escapeHtml(oneLiner)}</p>` : ""}
    ${coverMarkup}
    ${metaMarkup}
    <section class="description">
      ${paragraphs(description) || `<p>${escapeHtml(truncate(oneLiner || title, 280))}</p>`}
    </section>
    ${tagsMarkup}
    ${linksMarkup}
  </main>

  <footer class="site">
    <a href="/projects">Back to all projects</a>
    <a href="/">Build For Good</a>
  </footer>
</div>
</body>
</html>`;
}
